import { captureDiffBetweenTrees, emptyCapturedDiff, writeWorktreeTree } from "./gitDiffCapture";
import { AgentAdapter, CapturedDiff } from "./agentAdapter";
import { loadConfig } from "../config";
import { evaluateCapturedDiff } from "../filter";
import { runGeneration } from "../generation";
import {
  completeTurn,
  getCheckpointTree,
  insertCapturedDiff,
  setCheckpointTree,
  upsertTurn,
} from "../store";

/**
 * Fields Claude Code hooks send on stdin, as documented at
 * https://code.claude.com/docs/en/hooks (fetched live — this environment
 * had no way to run an authenticated live Claude Code session to observe
 * a real firing directly; see DECISIONS.md's "hook payload shape" entry
 * for exactly what was and wasn't possible to verify empirically).
 *
 * `session_id`/`cwd`/`hook_event_name` are documented as present on every
 * event and are treated as reliable. `prompt_id` is documented as "absent
 * until first user input" — plausible it's simply always present by the
 * time PreToolUse/PostToolUse/Stop can fire, but this wasn't independently
 * confirmed, so callers must not assume it's always set (see
 * `resolvePromptId` in this file for the defensive fallback).
 */
export interface ClaudeCodeHookPayload {
  session_id: string;
  prompt_id?: string;
  cwd: string;
  hook_event_name: string;
  tool_name?: string;
  tool_input?: unknown;
  tool_use_id?: string;
  tool_output?: unknown;
  tool_response_time_ms?: number;
  last_assistant_message?: string;
  tool_use_count?: number;
  tool_error_count?: number;
  // Forward-compatible: hook payloads may carry fields this type doesn't
  // model yet (transcript_path, permission_mode, effort, agent_id, ...).
  [key: string]: unknown;
}

/**
 * Used when a payload's `prompt_id` is missing. Falling back to a single
 * fixed key (rather than e.g. inventing a random one per call) means an
 * uncertain/absent prompt_id degrades to "one turn per whole session_id" —
 * i.e. exactly the coarser behavior the original (pre-verification) Phase 1
 * assumption described — rather than silently fragmenting into many
 * untracked pseudo-turns.
 */
const FALLBACK_PROMPT_ID = "__no_prompt_id__";

export function resolvePromptId(payload: Pick<ClaudeCodeHookPayload, "prompt_id">): string {
  return payload.prompt_id && payload.prompt_id.length > 0 ? payload.prompt_id : FALLBACK_PROMPT_ID;
}

/**
 * Adapts one Claude Code turn (session_id + prompt_id) to the Phase 2
 * AgentAdapter interface. A turn, not a whole interactive CLI session, is
 * this adapter's unit of work — see DECISIONS.md's "Stop fires per turn,
 * not per session" entry for why that's the correct binding for
 * onSessionComplete's "present before final output" semantics despite the
 * name.
 */
export class ClaudeCodeAdapter implements AgentAdapter {
  readonly supportsHeadlessSelfInvocation = true;
  readonly reportsCost = true;

  constructor(
    private readonly db: Database.Database,
    private readonly sessionId: string,
    private readonly promptId: string,
    private readonly repoPath: string
  ) {}

  /**
   * Checkpoint-based incremental capture: diffs the current working tree
   * against this session+repo's last recorded checkpoint (not always
   * HEAD), so a `PostToolUse` firing only ever surfaces what's genuinely
   * new since the *previous* firing — never the same unchanged diff twice,
   * and never pre-existing uncommitted work that predates this session.
   * See DECISIONS.md's "Checkpoint-based incremental capture" entry for
   * the full design (this fixes a real bug: every firing used to re-diff
   * the whole working tree against HEAD, so two firings with no new work
   * between them generated and paid for the same question twice).
   *
   * `ensureCheckpointSeeded()` is expected to have already run earlier in
   * this same hook invocation (see cli.ts's `runInternalHook`), so a
   * checkpoint should already exist by the time this is called — the
   * defensive re-seed below only matters if that invariant is ever broken.
   */
  checkAndCapture(): CapturedDiff {
    const currentTree = writeWorktreeTree(this.repoPath);
    const previousTree = getCheckpointTree(this.db, this.sessionId, this.repoPath);

    if (previousTree === null || previousTree === currentTree) {
      // Either the very first observation of this session+repo (nothing
      // "new" to report yet — this current state IS the baseline) or
      // nothing has changed since the last capture. Either way: advance
      // the checkpoint to the current state and report no diff.
      setCheckpointTree(this.db, this.sessionId, this.repoPath, currentTree);
      return emptyCapturedDiff(this.repoPath);
    }

    const diffHash = `${previousTree}..${currentTree}`;
    const diff = captureDiffBetweenTrees(this.repoPath, previousTree, currentTree, diffHash);
    setCheckpointTree(this.db, this.sessionId, this.repoPath, currentTree);

    if (diff.files.length > 0) {
      void this.onChangeDetected(diff);
    }
    return diff;
  }

  /**
   * Establishes this session+repo's checkpoint baseline on the FIRST hook
   * firing Grasp observes for it (of any event type — see cli.ts, which
   * calls this unconditionally before dispatching by event name, the same
   * place `ensureTurnStarted` already runs on every firing). Seeding here
   * rather than lazily inside `checkAndCapture` matters: `checkAndCapture`
   * only runs on `PostToolUse`, i.e. *after* a tool call already ran, so
   * seeding there would silently bake that first tool call's own changes
   * into the "already seen" baseline and never surface them. Seeding as
   * early as possible (typically the session's first `PreToolUse`, which
   * fires before any tool runs) is what makes the baseline genuinely
   * pre-agent-work. A cheap read (does a checkpoint already exist?) short-
   * circuits every firing after the first, so this costs real work
   * (building a tree snapshot) exactly once per session+repo.
   */
  ensureCheckpointSeeded(): void {
    if (getCheckpointTree(this.db, this.sessionId, this.repoPath) !== null) return;
    const tree = writeWorktreeTree(this.repoPath);
    setCheckpointTree(this.db, this.sessionId, this.repoPath, tree);
  }

  async onChangeDetected(diff: CapturedDiff): Promise<void> {
    // Persisting to captured_diffs IS part of this phase's job: a hook
    // firing is a background process with no attached terminal, so the
    // SQLite store (not stdout) is the only way this capture is observable
    // at all — unlike Phase 2's debug:capture, which had a human watching
    // a terminal. Every capture is run through Phase 4's mechanical filter
    // before being recorded — see DECISIONS.md's "Filtered-diff recording"
    // entry: a filtered-out diff still gets a row here (filtered=1,
    // filter_reason=<why>), it just never reaches generation.
    const { config } = loadConfig(this.repoPath);
    const verdict = evaluateCapturedDiff(diff, config);

    insertCapturedDiff(this.db, {
      sessionId: this.sessionId,
      promptId: this.promptId,
      repo: diff.repo,
      capturedAt: diff.capturedAt,
      diff,
      filtered: !verdict.passed,
      filterReason: verdict.reason,
    });

    // A passed diff goes straight into Phase 5's judge+generate call. The
    // cost cap is session-wide (see DECISIONS.md's "Resolving Phase 3's
    // flagged consequence" entry), so `runGeneration` sums cost across
    // this session_id, not just this turn, before deciding whether to
    // invoke `claude -p` at all.
    if (verdict.passed) {
      runGeneration(this.db, {
        sessionId: this.sessionId,
        repo: diff.repo,
        significantFiles: verdict.significantFiles,
        config,
        diffHash: diff.diffHash,
      });
    }
  }

  /**
   * Marks this turn complete. Idempotent: if some other invocation already
   * completed this exact (sessionId, promptId) turn, this safely does
   * nothing rather than re-running completion side effects. Flushing a
   * queue and presenting before final output is Phase 7/8 — this phase
   * only proves the "exactly once per turn" boundary is real and
   * detectable.
   */
  async onSessionComplete(): Promise<void> {
    completeTurn(this.db, { sessionId: this.sessionId, promptId: this.promptId });
  }

  /** Ensures the underlying cc_turns row exists, independent of which hook calls it first. */
  ensureTurnStarted(): void {
    upsertTurn(this.db, { sessionId: this.sessionId, promptId: this.promptId, repo: this.repoPath });
  }
}
import * as crypto from "crypto";
import * as fs from "fs";
import * as os from "os";
import * as path from "path";
import { isGitWorkTree, listUntrackedFiles, resolveBaseRef, runGit } from "../git";
import { AgentAdapter, CapturedDiff, DiffFile, DiffHunk, FileChangeStatus } from "./agentAdapter";

interface NameStatusEntry {
  status: FileChangeStatus;
  path: string;
  oldPath: string | null;
}

interface NumstatEntry {
  insertions: number;
  deletions: number;
}

const STATUS_LETTER_MAP: Record<string, FileChangeStatus> = {
  A: "added",
  M: "modified",
  D: "deleted",
  T: "modified", // file-type change (e.g. symlink <-> regular) — closest fit
};

/** Parses `git diff --name-status -M` output. */
function parseNameStatus(output: string): NameStatusEntry[] {
  return output
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => {
      const fields = line.split("\t");
      const code = fields[0];
      if (code.startsWith("R")) {
        return { status: "renamed" as const, oldPath: fields[1], path: fields[2] };
      }
      const status = STATUS_LETTER_MAP[code[0]] ?? "modified";
      return { status, oldPath: null, path: fields[1] };
    });
}

/** Parses `git diff --numstat -M` output, keyed by the file's new/current path. */
function parseNumstat(output: string): Map<string, NumstatEntry> {
  const map = new Map<string, NumstatEntry>();
  for (const line of output.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const [insRaw, delRaw, pathField] = trimmed.split("\t");
    // Binary files report "-" instead of a count.
    const insertions = insRaw === "-" ? 0 : Number(insRaw);
    const deletions = delRaw === "-" ? 0 : Number(delRaw);
    const newPath = pathField.includes(" => ") ? pathField.split(" => ")[1] : pathField;
    map.set(newPath, { insertions, deletions });
  }
  return map;
}

/** Splits a multi-file `git diff` output into one raw chunk per file. */
function splitIntoFileDiffs(rawDiffText: string): string[] {
  if (!rawDiffText.trim()) return [];
  return rawDiffText
    .split(/(?=^diff --git )/m)
    .map((chunk) => chunk.replace(/\n$/, ""))
    .filter((chunk) => chunk.trim().length > 0);
}

/** Pulls the file path a diff chunk applies to, from its `+++`/`---` header lines. */
function extractPathFromChunk(chunk: string): string | null {
  const lines = chunk.split("\n");
  const plusLine = lines.find((l) => l.startsWith("+++ "));
  const minusLine = lines.find((l) => l.startsWith("--- "));
  const fromHeader = (line: string | undefined): string | null => {
    if (!line || line === "+++ /dev/null" || line === "--- /dev/null") return null;
    // "+++ b/path/to/file" / "--- a/path/to/file" — strip the 6-char prefix.
    return line.slice(6);
  };
  return fromHeader(plusLine) ?? fromHeader(minusLine);
}

/** Extracts `@@ ... @@` hunks (header + body lines) from one file's diff chunk. */
function extractHunks(chunkOrDiffText: string): DiffHunk[] {
  const lines = chunkOrDiffText.split("\n");
  const hunks: DiffHunk[] = [];
  let current: DiffHunk | null = null;
  for (const line of lines) {
    if (line.startsWith("@@")) {
      if (current) hunks.push(current);
      current = { header: line, lines: [] };
    } else if (current) {
      current.lines.push(line);
    }
  }
  if (current) hunks.push(current);
  return hunks;
}

function countInsertions(hunks: DiffHunk[]): number {
  return hunks.reduce(
    (sum, h) => sum + h.lines.filter((l) => l.startsWith("+") && !l.startsWith("+++")).length,
    0
  );
}

/**
 * The same file-level diff parsing logic (name-status for status/rename,
 * numstat for insertion/deletion counts, raw diff text hand-split into
 * hunks by file), shared by `captureGitDiff` (single ref, HEAD-vs-worktree)
 * and `captureDiffBetweenTrees` (two tree-ish args) below — `git diff`'s
 * output format is identical either way, so this is one parser, not two.
 */
function diffFilesBetween(
  repoPath: string,
  fromArg: string,
  toArg: string | null
): { files: DiffFile[]; rawDiffText: string } {
  const refArgs = toArg !== null ? [fromArg, toArg] : [fromArg];
  const nameStatusOut = runGit(repoPath, ["diff", "--no-color", "-M", "--name-status", ...refArgs]).stdout;
  const numstatOut = runGit(repoPath, ["diff", "--no-color", "-M", "--numstat", ...refArgs]).stdout;
  const rawDiffText = runGit(repoPath, ["diff", "--no-color", "-M", ...refArgs]).stdout.replace(/\n$/, "");

  const statuses = parseNameStatus(nameStatusOut);
  const stats = parseNumstat(numstatOut);
  const chunks = splitIntoFileDiffs(rawDiffText);

  const files: DiffFile[] = statuses.map((entry) => {
    const stat = stats.get(entry.path) ?? { insertions: 0, deletions: 0 };
    const chunk = chunks.find((c) => {
      const chunkPath = extractPathFromChunk(c);
      return chunkPath === entry.path || (entry.oldPath !== null && chunkPath === entry.oldPath);
    });
    return {
      path: entry.path,
      oldPath: entry.oldPath,
      status: entry.status,
      insertions: stat.insertions,
      deletions: stat.deletions,
      hunks: chunk ? extractHunks(chunk) : [],
    };
  });

  return { files, rawDiffText };
}

/**
 * Captures the working-tree diff for a repo: everything changed since the
 * last commit (staged + unstaged, via `git diff HEAD`) plus untracked files
 * not excluded by .gitignore. Read-only — never touches the index.
 *
 * See DECISIONS.md's "Git-diff capture: comparison mechanism" entry for why
 * HEAD (not the index, not a stored snapshot) is the comparison base for
 * this function specifically — it's the right base for a manual, one-shot
 * "show me everything uncommitted right now" inspection command
 * (`debug:capture`/`GitDiffAdapter`). `ClaudeCodeAdapter`'s hook-driven
 * capture uses `captureDiffBetweenTrees` instead — see that function's own
 * doc comment for why HEAD is the wrong base there.
 */
export function captureGitDiff(repoPath: string): CapturedDiff {
  const absoluteRepoPath = path.resolve(repoPath);

  if (!isGitWorkTree(absoluteRepoPath)) {
    throw new Error(`Grasp: ${absoluteRepoPath} is not inside a git working tree.`);
  }

  const baseRef = resolveBaseRef(absoluteRepoPath);
  const { files: trackedFiles, rawDiffText: rawTrackedDiff } = diffFilesBetween(
    absoluteRepoPath,
    baseRef,
    null
  );

  const untrackedRawChunks: string[] = [];
  const untrackedFiles: DiffFile[] = listUntrackedFiles(absoluteRepoPath).map((filePath) => {
    // git diff --no-index exits 1 when it finds differences (expected, not an error).
    const diffText = runGit(
      absoluteRepoPath,
      ["diff", "--no-color", "--no-index", "--", "/dev/null", filePath],
      [0, 1]
    ).stdout;
    const trimmedDiffText = diffText.replace(/\n$/, "");
    untrackedRawChunks.push(trimmedDiffText);
    const hunks = extractHunks(trimmedDiffText);
    return {
      path: filePath,
      oldPath: null,
      status: "added",
      insertions: countInsertions(hunks),
      deletions: 0,
      hunks,
    };
  });

  const files = [...trackedFiles, ...untrackedFiles];
  const rawDiffText = [rawTrackedDiff.replace(/\n$/, ""), ...untrackedRawChunks]
    .filter((chunk) => chunk.length > 0)
    .join("\n");

  return {
    repo: absoluteRepoPath,
    capturedAt: new Date().toISOString(),
    files,
    rawDiffText,
    // No checkpoint concept on this path (see the module doc comment above
    // writeWorktreeTree/captureDiffBetweenTrees) — always HEAD-vs-worktree,
    // so there are no two endpoints to name a hash after.
    diffHash: null,
  };
}

// --- Checkpoint-based incremental capture (ClaudeCodeAdapter only) --------
//
// `captureGitDiff` above always diffs HEAD-vs-worktree — correct for a
// manual, one-shot inspection command (`debug:capture`/`GitDiffAdapter`,
// "show me everything uncommitted right now"), but wrong for a hook-driven
// capture that fires after every tool call: re-diffing the whole working
// tree every time re-surfaces the same accumulated changes on every firing
// with no new work in between, and can attribute uncommitted changes that
// predate the agent's turn entirely to the agent. See DECISIONS.md's
// "Checkpoint-based incremental capture" entry for the full design
// rationale and the alternatives that were considered and rejected.
//
// The mechanism: snapshot the exact current working tree (tracked +
// untracked, respecting .gitignore) as a real git tree object, using a
// throwaway index file (via `GIT_INDEX_FILE`) that's never wired up as the
// repo's real index — so this never stages anything a real `git status`/
// `git commit` would see. Two such snapshots taken at different times can
// then be diffed against EACH OTHER with the exact same `git diff`
// invocations already used above (tree-ish vs tree-ish behaves identically
// to ref vs ref for --name-status/--numstat/raw output), which is what
// makes an untracked file correctly show as "modified" rather than
// "deleted" between two checkpoints — a plain `git diff <tree>` against the
// live worktree does NOT do this correctly for untracked paths, since it's
// actually a tree-vs-INDEX comparison under the hood and the real index
// never has untracked entries at all (verified empirically before choosing
// this design — a tree-vs-worktree "single ref" diff for a tree containing
// an untracked file's prior snapshot showed it as *deleted*, not modified,
// even when the file was present and unchanged on disk).

/**
 * Builds a git tree object representing the exact current state of the
 * working tree (every tracked file's current content, plus every untracked
 * file not excluded by .gitignore) and returns its SHA. Never touches the
 * repo's real index — `GIT_INDEX_FILE` points `read-tree`/`add`/`write-tree`
 * at a throwaway file for the duration of this call, deleted afterward.
 */
export function writeWorktreeTree(repoPath: string): string {
  const absoluteRepoPath = path.resolve(repoPath);
  const seedRef = resolveBaseRef(absoluteRepoPath);
  const scratchIndexPath = path.join(
    os.tmpdir(),
    `grasp-idx-${process.pid}-${Date.now()}-${crypto.randomBytes(4).toString("hex")}`
  );
  try {
    const env = { GIT_INDEX_FILE: scratchIndexPath };
    runGit(absoluteRepoPath, ["read-tree", seedRef], [0], env);
    runGit(absoluteRepoPath, ["add", "-A"], [0], env);
    const { stdout } = runGit(absoluteRepoPath, ["write-tree"], [0], env);
    return stdout.trim();
  } finally {
    fs.rmSync(scratchIndexPath, { force: true });
  }
}

/**
 * Diffs two `writeWorktreeTree` snapshots against each other (via the same
 * `diffFilesBetween` parser defined above `captureGitDiff`) — the actual
 * incremental-capture primitive `ClaudeCodeAdapter.checkAndCapture` uses.
 * `diffHash` is the caller's job to compute (conventionally
 * `${fromTree}..${toTree}`, git's own range-diff notation — a real,
 * reproducible identifier a developer could hand back to `git diff`
 * themselves) since this function only knows the two tree SHAs, not what
 * convention the caller wants recorded.
 */
export function captureDiffBetweenTrees(
  repoPath: string,
  fromTree: string,
  toTree: string,
  diffHash: string
): CapturedDiff {
  const absoluteRepoPath = path.resolve(repoPath);
  const { files, rawDiffText } = diffFilesBetween(absoluteRepoPath, fromTree, toTree);
  return {
    repo: absoluteRepoPath,
    capturedAt: new Date().toISOString(),
    files,
    rawDiffText,
    diffHash,
  };
}

/** A capture with no changes — used both when a checkpoint is freshly seeded (nothing "new" yet by definition) and when two consecutive checkpoints are identical (nothing changed since the last capture). */
export function emptyCapturedDiff(repoPath: string): CapturedDiff {
  return {
    repo: path.resolve(repoPath),
    capturedAt: new Date().toISOString(),
    files: [],
    rawDiffText: "",
    diffHash: null,
  };
}

/**
 * Adapter-shaped wrapper around `captureGitDiff`. Agent-agnostic: works
 * against any git repo regardless of which coding agent (if any) produced
 * the changes, which is why it reports no headless generation capability
 * and no cost self-reporting of its own — those are properties of a
 * specific coding agent's CLI, not of git itself.
 */
export class GitDiffAdapter implements AgentAdapter {
  readonly supportsHeadlessSelfInvocation = false;
  readonly reportsCost = false;

  constructor(private readonly repoPath: string) {}

  /**
   * Captures the current diff and, if non-empty, notifies via
   * onChangeDetected. This is the shape a future poll loop would call on
   * an interval; nothing calls it on a timer yet in Phase 2. Returns the
   * diff (including empty results) so callers like the debug CLI can
   * inspect it directly without depending on the notification path.
   */
  checkForChanges(): CapturedDiff {
    const diff = captureGitDiff(this.repoPath);
    if (diff.files.length > 0) {
      void this.onChangeDetected(diff);
    }
    return diff;
  }

  async onChangeDetected(_diff: CapturedDiff): Promise<void> {
    // Phase 4's mechanical filter (src/filter.ts) exists and is wired into
    // ClaudeCodeAdapter, which already has a DB handle and a session/turn
    // to record against. GitDiffAdapter has neither (it's a manual/poll
    // capture with no hook-driven session concept), so there's nowhere
    // meaningful to persist a filter verdict yet — see DECISIONS.md's
    // "Filter wiring scope" entry. Forwarding a passed diff into real
    // question generation is still Phase 5 regardless.
  }

  async onSessionComplete(): Promise<void> {
    // Flushing the queue and presenting before final output is Phase 7/8.
  }
}
import { CapturedDiff, DiffFile, DiffHunk } from "./adapters/agentAdapter";
import { BASELINE_IGNORE_PATTERNS } from "./ignoreBaseline";
import { GraspConfig } from "./types";

/**
 * Purely mechanical pre-filtering (brief §5.2's mechanical half only — no
 * semantic "is this interesting" judgment lives here; see DECISIONS.md's
 * "Flagged-pattern filtering" entry from Phase 4's planning and the
 * formatting-only/filtered-diff-recording entries added in this phase).
 */

export type FilterReason =
  | "baseline_ignore"
  | "user_ignore_pattern"
  | "formatting_only"
  | "below_min_threshold"
  | "above_max_threshold";

export type FileExclusionReason = "baseline_ignore" | "user_ignore_pattern" | "formatting_only";

export interface ExcludedFile {
  path: string;
  reason: FileExclusionReason;
}

export interface FilterResult {
  passed: boolean;
  reason: FilterReason | null;
  /**
   * Files that survived exclusion — what a future Phase 5 should actually
   * operate on. Empty whenever `passed` is false.
   */
  significantFiles: DiffFile[];
  excludedFiles: ExcludedFile[];
  totalChangedLines: number;
  maxSingleFileChangedLines: number;
}

// --- Ignore-pattern matching -------------------------------------------

/**
 * A pattern ending in "/" matches a directory anywhere in the path (e.g.
 * "node_modules/" matches "packages/a/node_modules/x.js"). Anything else
 * matches by exact basename or exact full relative path (e.g.
 * "package-lock.json" matches both "package-lock.json" and
 * "packages/a/package-lock.json"). No glob syntax — see DECISIONS.md's
 * "Ignore-pattern matching syntax" entry for why.
 */
export function matchesIgnorePattern(filePath: string, pattern: string): boolean {
  const normalizedPath = filePath.replace(/\\/g, "/").replace(/^\.\//, "");
  if (pattern.endsWith("/")) {
    const dirName = pattern.slice(0, -1);
    const dirSegments = normalizedPath.split("/").slice(0, -1);
    return dirSegments.includes(dirName);
  }
  const basename = normalizedPath.split("/").pop() ?? normalizedPath;
  return basename === pattern || normalizedPath === pattern;
}

function classifyIgnoreExclusion(filePath: string, config: GraspConfig): FileExclusionReason | null {
  if (BASELINE_IGNORE_PATTERNS.some((p) => matchesIgnorePattern(filePath, p))) {
    return "baseline_ignore";
  }
  if (config.ignorePatterns.some((p) => matchesIgnorePattern(filePath, p))) {
    return "user_ignore_pattern";
  }
  return null;
}

// --- Formatting-only detection ------------------------------------------

/**
 * Collapses insignificant whitespace: trims the line and collapses any run
 * of internal whitespace to a single space. Reindentation, trailing
 * whitespace, and tabs-vs-spaces all normalize identically; anything that
 * changes actual tokens does not.
 */
function normalizeLine(line: string): string {
  return line.trim().replace(/\s+/g, " ");
}

/** A hunk's removed lines (with their `-` prefix stripped), normalized, in order. */
function normalizedRemovedLines(hunk: DiffHunk): string[] {
  return hunk.lines
    .filter((l) => l.startsWith("-") && !l.startsWith("---"))
    .map((l) => normalizeLine(l.slice(1)));
}

/** A hunk's added lines (with their `+` prefix stripped), normalized, in order. */
function normalizedAddedLines(hunk: DiffHunk): string[] {
  return hunk.lines
    .filter((l) => l.startsWith("+") && !l.startsWith("+++"))
    .map((l) => normalizeLine(l.slice(1)));
}

function arraysEqual(a: string[], b: string[]): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

/**
 * A hunk is formatting-only if its normalized removed-line sequence exactly
 * equals its normalized added-line sequence (same content, same order —
 * order matters so a real reordering of statements is never mistaken for
 * formatting). A hunk with no removed/added lines at all (shouldn't happen
 * in practice, but) counts as formatting-only vacuously.
 */
function isHunkFormattingOnly(hunk: DiffHunk): boolean {
  return arraysEqual(normalizedRemovedLines(hunk), normalizedAddedLines(hunk));
}

/** A file is formatting-only only if every one of its hunks is. */
export function isFileFormattingOnly(file: DiffFile): boolean {
  if (file.hunks.length === 0) return false;
  return file.hunks.every(isHunkFormattingOnly);
}

// --- Main filter ----------------------------------------------------------

function pickEmptyReason(excludedFiles: ExcludedFile[]): FilterReason {
  // Priority: a user-specified pattern is the most intentional signal, then
  // the baseline list, then formatting-only (the most inferred of the
  // three). Only matters when a multi-file diff is emptied by a mix of
  // reasons — none of Phase 4's own verification scenarios hit this, but
  // the order needs to be defined rather than left to iteration order.
  if (excludedFiles.some((f) => f.reason === "user_ignore_pattern")) return "user_ignore_pattern";
  if (excludedFiles.some((f) => f.reason === "baseline_ignore")) return "baseline_ignore";
  return "formatting_only";
}

/**
 * Applies Phase 4's mechanical filter to a captured diff. Two file-level
 * exclusion passes run first (ignore patterns, then formatting-only),
 * producing a "significant files" set; size thresholds are then evaluated
 * against ONLY that remaining set — so a file excluded by either pass
 * doesn't count toward or against the size thresholds. See DECISIONS.md's
 * "Diff-size thresholds: per-file exclusion, not whole-diff" entry.
 */
export function evaluateCapturedDiff(diff: CapturedDiff, config: GraspConfig): FilterResult {
  const excludedFiles: ExcludedFile[] = [];
  const significantFiles: DiffFile[] = [];

  for (const file of diff.files) {
    const ignoreReason = classifyIgnoreExclusion(file.path, config);
    if (ignoreReason) {
      excludedFiles.push({ path: file.path, reason: ignoreReason });
      continue;
    }
    if (isFileFormattingOnly(file)) {
      excludedFiles.push({ path: file.path, reason: "formatting_only" });
      continue;
    }
    significantFiles.push(file);
  }

  if (significantFiles.length === 0) {
    return {
      passed: false,
      reason: pickEmptyReason(excludedFiles),
      significantFiles: [],
      excludedFiles,
      totalChangedLines: 0,
      maxSingleFileChangedLines: 0,
    };
  }

  const fileSizes = significantFiles.map((f) => f.insertions + f.deletions);
  const totalChangedLines = fileSizes.reduce((sum, n) => sum + n, 0);
  const maxSingleFileChangedLines = Math.max(...fileSizes);

  const { minChangedLines, maxTotalChangedLines, maxSingleFileChangedLines: maxSingleFileCap } =
    config.diffThresholds;

  if (totalChangedLines > maxTotalChangedLines || maxSingleFileChangedLines > maxSingleFileCap) {
    return {
      passed: false,
      reason: "above_max_threshold",
      significantFiles: [],
      excludedFiles,
      totalChangedLines,
      maxSingleFileChangedLines,
    };
  }

  const anyFileClearsMinimum = fileSizes.some((size) => size >= minChangedLines);
  if (!anyFileClearsMinimum) {
    return {
      passed: false,
      reason: "below_min_threshold",
      significantFiles: [],
      excludedFiles,
      totalChangedLines,
      maxSingleFileChangedLines,
    };
  }

  return {
    passed: true,
    reason: null,
    significantFiles,
    excludedFiles,
    totalChangedLines,
    maxSingleFileChangedLines,
  };
}

#!/usr/bin/env node
import * as fs from "fs";
import * as path from "path";
import { ClaudeCodeAdapter, ClaudeCodeHookPayload, resolvePromptId } from "./adapters/claudeCodeAdapter";
import { GitDiffAdapter } from "./adapters/gitDiffCapture";
import { loadConfig } from "./config";
import { evaluateCapturedDiff } from "./filter";
import {
  getConceptTagsByEventId,
  getEventById,
  getPendingQuestionsForSession,
  getSessionCostUsd,
  insertEvent,
  markEventAnswered,
  openStore,
  recordHookInvocation,
} from "./store";
import { runInit } from "./init";
import { runReview } from "./review";

function readPackageVersion(): string {
  const pkgPath = path.join(__dirname, "..", "package.json");
  const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf-8"));
  return pkg.version as string;
}

const HELP_TEXT = `grasp — gate AI-coding-agent output behind comprehension questions

Usage:
  grasp --version                Print the installed version
  grasp --help                   Show this help
  grasp init                     Install Grasp's Claude Code hooks into this repo (asks for confirmation)
  grasp review                   Work through pending comprehension questions, interactively
  grasp debug:seed               (dev) Insert one fake event + concept tag, for verifying the local store
  grasp debug:capture <repo>     (dev) Run git-diff capture against <repo> and print the resulting diff object
  grasp debug:answer <event-id>  (dev) Simulate answering an event's concept question (marks its concept tag(s) answered)
  grasp internal:hook            (internal) Claude Code hook entrypoint — reads a hook payload on stdin

v1 status: config loading, local storage, git-diff capture, Claude Code
hook-based capture, mechanical meaningful-change filtering, headless
judge+generate question generation, \`grasp review\` for answering questions
interactively (soft-nudge visibility + opt-in hard-gate), a session-wide
questions-per-session cap with coherent batch grouping/ordering in
\`grasp review\`, and a session-end cost summary + pending-question nudge
surfaced via \`Stop\`'s systemMessage. See README.md for the full picture.
\`grasp watch\` (persistent, auto-popping review) is not built.
`;

function printHelp(): void {
  process.stdout.write(HELP_TEXT);
}

/**
 * Every invocation ensures ~/.grasp/config.json and ~/.grasp/history.db
 * exist (creating them with defaults on first run) — not just debug:seed.
 * This is what makes "first run" in BUILD_PLAN.md's verification steps
 * true regardless of which command the user runs first.
 */
function ensureInitialized(repoRoot: string) {
  const loaded = loadConfig(repoRoot);
  const db = openStore();
  db.close();
  return loaded;
}

function runDebugSeed(): void {
  const repoRoot = process.cwd();
  const { config, globalConfigPath, repoConfigPath } = loadConfig(repoRoot);
  const db = openStore();

  const eventId = insertEvent(
    db,
    {
      timestamp: new Date().toISOString(),
      repo: repoRoot,
      sessionId: null,
      diffHash: "debug-seed-hash",
      diffSummary: "1 file changed, 4 insertions(+), 1 deletion(-)",
      questionConcept:
        "What's the difference between a mutex and a channel for coordinating goroutines?",
      questionInstance: "Given that, why did this change protect `cache` with a mutex?",
      questionType: "both",
      generationSource: "debug:seed",
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: 0.0031,
      diffFiles: [
        {
          path: "cache.go",
          oldPath: null,
          status: "modified",
          insertions: 4,
          deletions: 1,
          hunks: [
            {
              header: "@@ -10,5 +10,8 @@ type Cache struct {",
              lines: [
                " type Cache struct {",
                "-  data map[string]string",
                "+  mu   sync.Mutex",
                "+  data map[string]string",
                " }",
              ],
            },
          ],
        },
      ],
    },
    [{ tag: "mutex-vs-channel", answered: false }]
  );

  const tags = getConceptTagsByEventId(db, eventId);

  process.stdout.write(
    [
      `Inserted debug event id=${eventId} into ${db.name}`,
      `Linked concept_tags rows: ${tags.map((t) => `id=${t.id} tag=${t.tag}`).join(", ")}`,
      `Config loaded from: ${globalConfigPath}${
        repoConfigPath ? ` (overridden by ${repoConfigPath})` : " (no repo override present)"
      }`,
      `gateMode=${config.gateMode} questionsPerSessionCap=${config.questionsPerSessionCap}`,
      "",
    ].join("\n")
  );

  db.close();
}

function runDebugAnswer(eventIdArg: string | undefined): void {
  const eventId = Number(eventIdArg);
  if (!eventIdArg || !Number.isInteger(eventId)) {
    process.stderr.write("Usage: grasp debug:answer <event-id>\n");
    process.exitCode = 1;
    return;
  }

  const db = openStore();
  try {
    const event = getEventById(db, eventId);
    if (!event) {
      process.stderr.write(`No event with id=${eventId} found in ${db.name}\n`);
      process.exitCode = 1;
      return;
    }

    const tags = markEventAnswered(db, eventId, {
      answerConcept: event.questionConcept ? "(debug:answer stub) understood" : null,
      answerInstance: event.questionInstance ? "(debug:answer stub) understood" : null,
    });

    process.stdout.write(
      [
        `Marked event id=${eventId} answered.`,
        tags.length > 0
          ? `concept_tags now answered: ${tags.join(", ")}`
          : "(this event had no linked concept_tags — nothing to mark)",
        "",
      ].join("\n")
    );
  } finally {
    db.close();
  }
}

function runDebugCapture(repoPathArg: string | undefined): void {
  if (!repoPathArg) {
    process.stderr.write("Usage: grasp debug:capture <repo-path>\n");
    process.exitCode = 1;
    return;
  }

  const adapter = new GitDiffAdapter(repoPathArg);
  const diff = adapter.checkForChanges();

  if (diff.files.length === 0) {
    process.stdout.write(`No changes detected in ${diff.repo}\n`);
    return;
  }

  const summaryLines = diff.files.map(
    (f) =>
      `  ${f.status.padEnd(8)} ${f.oldPath ? `${f.oldPath} -> ` : ""}${f.path}  (+${f.insertions}/-${f.deletions}, ${f.hunks.length} hunk${f.hunks.length === 1 ? "" : "s"})`
  );

  const { config } = loadConfig(diff.repo);
  const verdict = evaluateCapturedDiff(diff, config);
  const filterLines = verdict.passed
    ? [
        `PASSED — ${verdict.significantFiles.length} significant file(s), ${verdict.totalChangedLines} changed lines total (max single file: ${verdict.maxSingleFileChangedLines})`,
      ]
    : [`FILTERED — reason: ${verdict.reason}`];
  if (verdict.excludedFiles.length > 0) {
    filterLines.push(
      "  excluded:",
      ...verdict.excludedFiles.map((f) => `    ${f.path} (${f.reason})`)
    );
  }

  process.stdout.write(
    [
      `Captured diff for ${diff.repo} at ${diff.capturedAt}`,
      `${diff.files.length} file(s) changed:`,
      ...summaryLines,
      "",
      "--- Phase 4 filter verdict ---",
      ...filterLines,
      "",
      "--- full CapturedDiff object (JSON) ---",
      JSON.stringify(diff, null, 2),
      "",
    ].join("\n")
  );
}

function readStdin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let data = "";
    process.stdin.setEncoding("utf-8");
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => resolve(data));
    process.stdin.on("error", reject);
  });
}

/**
 * "There's still a pending question for this session" message, shared by
 * the PreToolUse deny reason and the Stop systemMessage nudge so the two
 * don't drift into inconsistent wording.
 */
function pendingQuestionsMessage(count: number): string {
  return `${count} question${count === 1 ? "" : "s"} waiting — run \`grasp review\` to answer ${count === 1 ? "it" : "them"}.`;
}

/**
 * Brief §3.3's "cumulative session spend visible to the user, not just
 * logged" — see DECISIONS.md's "session-end cost summary" entry for why
 * this lives on `Stop` (the only channel a hook has to say anything at
 * all) and why 4 decimal places (real per-call costs are sub-cent; 2
 * decimals would round most of them to "$0.00" and hide the exact signal
 * the cap/summary exist to surface).
 */
function costSummaryMessage(costUsd: number): string {
  return `$${costUsd.toFixed(4)} spent generating comprehension questions this session so far.`;
}

/**
 * Claude Code hook entrypoint. Must NEVER throw, hang, or exit non-zero —
 * a hook that crashes would block the user's real Claude Code session
 * regardless of gateMode. Every failure mode below is caught and
 * swallowed rather than propagated. Hooks never render UI themselves (see
 * DECISIONS.md's TTY-access finding) — they only write state and, for
 * PreToolUse under hard-gate, emit the documented deny JSON; presentation
 * always happens in a separately-launched `grasp review`.
 */
async function runInternalHook(): Promise<void> {
  let raw: string;
  try {
    raw = await readStdin();
  } catch {
    return;
  }

  let payload: ClaudeCodeHookPayload;
  try {
    payload = JSON.parse(raw);
  } catch {
    return;
  }

  const sessionId = payload.session_id;
  const eventName = payload.hook_event_name;
  const cwd = payload.cwd;
  if (!sessionId || !eventName || !cwd) {
    return;
  }

  const promptId = resolvePromptId(payload);
  let hookOutput: Record<string, unknown> | null = null;

  try {
    const db = openStore();
    try {
      recordHookInvocation(db, { sessionId, promptId, eventName });
      const adapter = new ClaudeCodeAdapter(db, sessionId, promptId, cwd);
      adapter.ensureTurnStarted();
      // Unconditional on every firing, same as ensureTurnStarted above — a
      // cheap read that only does real work (building a tree snapshot) the
      // first time this session+repo is ever seen. Must run before any
      // PostToolUse capture so the checkpoint baseline reflects the state
      // BEFORE the first tool call, not after — see DECISIONS.md's
      // "Checkpoint-based incremental capture" entry.
      adapter.ensureCheckpointSeeded();

      if (eventName === "PostToolUse") {
        adapter.checkAndCapture();
      } else if (eventName === "Stop") {
        await adapter.onSessionComplete();
        // Visibility nudge — applies in BOTH gate modes, since it's the
        // only channel a hook actually has for reaching the user (the
        // narrowly-restricted terminalSequence field aside). See
        // DECISIONS.md's "gate-check scope" entry for why this is
        // session_id-scoped, matching the hard-gate check below. The cost
        // summary is combined into the same message when both apply — see
        // DECISIONS.md's "session-end cost summary" entry for why this is
        // the one place it surfaces and why the two independently-gated
        // pieces (pending count, spend) combine rather than firing as
        // separate messages.
        const pending = getPendingQuestionsForSession(db, sessionId);
        const spentSoFar = getSessionCostUsd(db, sessionId);
        const messageParts: string[] = [];
        if (pending.length > 0) messageParts.push(pendingQuestionsMessage(pending.length));
        if (spentSoFar > 0) messageParts.push(costSummaryMessage(spentSoFar));
        if (messageParts.length > 0) {
          hookOutput = { systemMessage: messageParts.join(" ") };
        }
      } else if (eventName === "PreToolUse") {
        const { config } = loadConfig(cwd);
        if (config.gateMode === "hard") {
          const pending = getPendingQuestionsForSession(db, sessionId);
          if (pending.length > 0) {
            hookOutput = {
              hookSpecificOutput: {
                hookEventName: "PreToolUse",
                permissionDecision: "deny",
                permissionDecisionReason: pendingQuestionsMessage(pending.length),
              },
            };
          }
        }
      }
    } finally {
      db.close();
    }
  } catch (err) {
    try {
      process.stderr.write(`grasp internal:hook: ${(err as Error).message}\n`);
    } catch {
      // even the error report must not throw
    }
    return;
  }

  if (hookOutput) {
    try {
      process.stdout.write(JSON.stringify(hookOutput));
    } catch {
      // never let a stdout write failure propagate either
    }
  }
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const command = args[0];

  ensureInitialized(process.cwd());

  if (command === undefined || command === "--help" || command === "-h") {
    printHelp();
    return;
  }

  if (command === "--version" || command === "-v") {
    process.stdout.write(`${readPackageVersion()}\n`);
    return;
  }

  if (command === "debug:seed") {
    runDebugSeed();
    return;
  }

  if (command === "debug:capture") {
    runDebugCapture(args[1]);
    return;
  }

  if (command === "debug:answer") {
    runDebugAnswer(args[1]);
    return;
  }

  if (command === "internal:hook") {
    await runInternalHook();
    return;
  }

  if (command === "init") {
    await runInit(process.cwd());
    return;
  }

  if (command === "review") {
    await runReview();
    return;
  }

  process.stderr.write(`Unknown command: ${command}\n\n`);
  printHelp();
  process.exitCode = 1;
}

main().catch((err) => {
  process.stderr.write(`${(err as Error).message}\n`);
  process.exitCode = 1;
});
import { execFileSync } from "child_process";
import Database from "better-sqlite3";
import { DiffFile } from "./adapters/agentAdapter";
import { GraspConfig } from "./types";
import {
  getAllAnsweredConceptTags,
  getConceptTagGlobal,
  getSessionCostUsd,
  getSessionQuestionCount,
  insertEvent,
} from "./store";

/**
 * The single generation path from brief §3.3: one headless `claude -p`
 * call that judges whether a diff is worth a question AND generates the
 * question(s) in the same response. Prompt/response contract design is
 * this phase's own — see DECISIONS.md's "Judge+generate prompt and
 * response contract" entry for the reasoning.
 */

const GENERATION_SOURCE = "headless-claude-p";

/**
 * Ceiling on the `claude -p` subprocess call itself. Deliberately well
 * under the Phase 5 outer Claude Code hook timeout (45s, src/init.ts) —
 * see DECISIONS.md's "Generation subprocess timeout value" entry for the
 * margin reasoning. Hardcoded, not exposed in GraspConfig — see
 * DECISIONS.md's "hardcoded vs configurable" entry for why.
 */
const GENERATION_TIMEOUT_MS = 20_000;

export type MissReason = "cap_reached" | "error" | "timeout";

export interface GenerationOutcome {
  eventId: number;
  missReason: MissReason | null;
  questionType: "concept" | "instance" | "both" | null;
}

export interface GenerationParams {
  sessionId: string;
  repo: string;
  significantFiles: DiffFile[];
  config: GraspConfig;
  /** From `CapturedDiff.diffHash` — see DECISIONS.md's "Checkpoint-based incremental capture" entry. Null when the capturing adapter doesn't compute one. */
  diffHash: string | null;
}

// --- diff_summary (local, deterministic, no model call) -------------------

export function buildDiffSummary(files: DiffFile[]): string {
  const totalInsertions = files.reduce((sum, f) => sum + f.insertions, 0);
  const totalDeletions = files.reduce((sum, f) => sum + f.deletions, 0);
  const fileList = files.map((f) => f.path).join(", ");
  return `${files.length} file${files.length === 1 ? "" : "s"} changed (+${totalInsertions}/-${totalDeletions}): ${fileList}`;
}

// --- prompt construction ----------------------------------------------------

/** Renders significant files as readable "File: ... / @@ hunk @@ / lines" text — the hunk data already IS unified-diff shaped, so no reconstruction of diff --git headers is needed for a model that just needs to read the change. */
function formatDiffForPrompt(files: DiffFile[]): string {
  return files
    .map((file) => {
      const header = `File: ${file.path} (${file.status}, +${file.insertions}/-${file.deletions})`;
      const hunkText = file.hunks
        .map((h) => [h.header, ...h.lines].join("\n"))
        .join("\n");
      return hunkText ? `${header}\n${hunkText}` : header;
    })
    .join("\n\n");
}

function buildJudgePrompt(diffText: string, answeredTags: string[]): string {
  const answeredList = answeredTags.length > 0 ? answeredTags.join(", ") : "none yet";
  return `You are a code-comprehension tutor helping a developer understand a change an AI coding agent just made to their own codebase.

Below is a diff the agent produced. Decide, in this single response:
1. Is this diff worth asking the developer a comprehension question about? Trivial, self-explanatory, or purely mechanical changes are not worth asking about.
2. If worth asking about, pick ONE concept tag naming the general programming concept this diff exercises (e.g. "mutex-vs-channel", "recursion", "sql-injection", "async-await", "binary-search"). Use a short, reusable, kebab-case tag — the same underlying concept in a different file should get the same tag.
3. Check the developer's already-answered concept tags below. If your chosen tag is already in that list, do NOT write a concept question — write the instance question only.
4. If a concept question is warranted (tag not already answered), write one: it tests/teaches the general idea, independent of this specific codebase.
5. Write an instance question that applies the concept directly to this diff. If a concept question was written, the instance question should be answerable BECAUSE of it. If no concept question was written (already known), the instance question should stand alone, referencing the diff directly.

Developer's already-answered concept tags (do not re-teach these): ${answeredList}

Diff:
${diffText}

Respond with ONLY a single JSON object, no other text, no markdown code fence, matching exactly this shape:
{"worthAsking": boolean, "conceptTag": string | null, "questionConcept": string | null, "questionInstance": string | null}

Rules for the JSON:
- If worthAsking is false: conceptTag, questionConcept, and questionInstance must all be null.
- If worthAsking is true: conceptTag must be a non-empty kebab-case string, and questionInstance must be a non-empty string.
- questionConcept must be null if conceptTag is in the already-answered list above; otherwise it must be a non-empty string.`;
}

// --- claude -p invocation and response parsing -----------------------------

interface ClaudeEnvelope {
  /**
   * Null when `total_cost_usd` was missing or not a number in the response
   * — genuinely unknown, never coerced to 0. A response can't be trusted
   * for cap accounting without a real cost figure; see DECISIONS.md's
   * "Missing total_cost_usd treated as unknown, not zero" entry.
   */
  totalCostUsd: number | null;
  resultText: string;
  isError: boolean;
}

/** True when a caught execFileSync error is specifically a timeout kill, not any other failure (spawn error, nonzero exit, ...). Empirically verified (not assumed) against this Node version: a timeout sets `error.code === "ETIMEDOUT"` — `error.killed` is NOT reliably `true` the way Node's own docs might suggest, and `error.signal === "SIGTERM"` alone isn't a safe-enough signal on its own since a process could plausibly exit via SIGTERM for unrelated reasons. See DECISIONS.md's "Timeout detection mechanism" entry. */
export function isTimeoutError(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { code?: unknown }).code === "ETIMEDOUT";
}

/** Shells out to `claude -p`, exactly per brief §3.3's recommended invocation shape. Throws if the process fails, times out, or its stdout isn't valid JSON at all — callers must catch, and can use `isTimeoutError` to distinguish a timeout from any other failure. */
function invokeClaudeJudge(prompt: string): ClaudeEnvelope {
  const stdout = execFileSync(
    "claude",
    ["-p", prompt, "--output-format", "json", "--allowedTools", "", "--max-turns", "1"],
    { encoding: "utf-8", maxBuffer: 1024 * 1024 * 16, timeout: GENERATION_TIMEOUT_MS }
  );
  const envelope = JSON.parse(stdout);
  return {
    totalCostUsd: typeof envelope.total_cost_usd === "number" ? envelope.total_cost_usd : null,
    resultText: typeof envelope.result === "string" ? envelope.result : "",
    isError: Boolean(envelope.is_error),
  };
}

export interface JudgeResponse {
  worthAsking: boolean;
  conceptTag: string | null;
  questionConcept: string | null;
  questionInstance: string | null;
}

/** Strips a ```json ... ``` / ``` ... ``` fence if the model wrapped its JSON in one despite instructions not to. */
function extractJsonBlock(text: string): string {
  const trimmed = text.trim();
  const fenceMatch = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  return fenceMatch ? fenceMatch[1].trim() : trimmed;
}

/** Returns null for anything that doesn't match the contract — malformed JSON, wrong types, or an internally inconsistent shape. Never throws. */
export function parseJudgeResponse(raw: string): JudgeResponse | null {
  let obj: any;
  try {
    obj = JSON.parse(extractJsonBlock(raw));
  } catch {
    return null;
  }
  if (typeof obj !== "object" || obj === null) return null;
  if (typeof obj.worthAsking !== "boolean") return null;

  if (obj.worthAsking === false) {
    if (obj.conceptTag !== null || obj.questionConcept !== null || obj.questionInstance !== null) {
      return null;
    }
    return { worthAsking: false, conceptTag: null, questionConcept: null, questionInstance: null };
  }

  if (typeof obj.conceptTag !== "string" || obj.conceptTag.trim().length === 0) return null;
  if (typeof obj.questionInstance !== "string" || obj.questionInstance.trim().length === 0) return null;
  if (
    obj.questionConcept !== null &&
    (typeof obj.questionConcept !== "string" || obj.questionConcept.trim().length === 0)
  ) {
    return null;
  }

  return {
    worthAsking: true,
    conceptTag: obj.conceptTag.trim(),
    questionConcept: typeof obj.questionConcept === "string" ? obj.questionConcept.trim() : null,
    questionInstance: obj.questionInstance.trim(),
  };
}

// --- main entry point --------------------------------------------------------

function recordMiss(
  db: Database.Database,
  params: GenerationParams,
  diffSummary: string,
  missReason: MissReason,
  costUsd: number | null
): GenerationOutcome {
  const eventId = insertEvent(db, {
    timestamp: new Date().toISOString(),
    repo: params.repo,
    sessionId: params.sessionId,
    diffHash: params.diffHash,
    diffSummary,
    questionConcept: null,
    questionInstance: null,
    questionType: null,
    generationSource: GENERATION_SOURCE,
    missReason,
    answerConcept: null,
    answerInstance: null,
    skipped: false,
    skipReason: null,
    costUsd,
    diffFiles: null,
  });
  return { eventId, missReason, questionType: null };
}

/**
 * Given a diff that already passed Phase 4's mechanical filter, enforces
 * the session-wide cost cap, then (if not capped) runs the single judge+
 * generate call and writes exactly one `events` row — whether or not it
 * produced a question. See DECISIONS.md's prompt/response-contract and
 * malformed-response entries for the design reasoning.
 */
export function runGeneration(db: Database.Database, params: GenerationParams): GenerationOutcome {
  const { sessionId, significantFiles, config } = params;
  const diffSummary = buildDiffSummary(significantFiles);

  const spentSoFar = getSessionCostUsd(db, sessionId);
  if (spentSoFar >= config.costCapUsd) {
    // Cap already met/exceeded — never invoke `claude -p` at all.
    return recordMiss(db, params, diffSummary, "cap_reached", null);
  }

  const questionsSoFar = getSessionQuestionCount(db, sessionId);
  if (questionsSoFar >= config.questionsPerSessionCap) {
    // Same "never invoke claude -p at all" pattern as the cost cap above,
    // and the same miss_reason — see DECISIONS.md's "Questions-per-session
    // cap: miss-reason reuse" entry for why cap_reached is shared rather
    // than a new value, and for how the two remain distinguishable after
    // the fact from the session's own cost/question totals at the time.
    return recordMiss(db, params, diffSummary, "cap_reached", null);
  }

  const answeredTags = getAllAnsweredConceptTags(db);
  const diffText = formatDiffForPrompt(significantFiles);
  const prompt = buildJudgePrompt(diffText, answeredTags);

  let envelope: ClaudeEnvelope;
  try {
    envelope = invokeClaudeJudge(prompt);
  } catch (err) {
    // Process never produced a usable envelope at all — no cost figure to
    // record either way (genuinely unknown, not 0). A timeout kill is
    // distinguished from every other spawn/exit failure specifically —
    // see isTimeoutError's own comment for how that's actually detected.
    const missReason: MissReason = isTimeoutError(err) ? "timeout" : "error";
    return recordMiss(db, params, diffSummary, missReason, null);
  }

  if (envelope.isError) {
    return recordMiss(db, params, diffSummary, "error", envelope.totalCostUsd);
  }

  if (envelope.totalCostUsd === null) {
    // A well-formed, non-error envelope that's missing its own cost figure
    // can't be trusted for cap accounting — recording it as a "free"
    // successful call would let repeated uncosted responses bypass the
    // cost cap entirely (it sums cost_usd, and NULL contributes 0). Treat
    // it as a miss instead — see DECISIONS.md's "Missing total_cost_usd"
    // entry. This intentionally never reaches parseJudgeResponse: even a
    // perfectly well-formed question in this response isn't recorded,
    // since there's no way to know what it actually cost.
    return recordMiss(db, params, diffSummary, "error", null);
  }

  const parsed = parseJudgeResponse(envelope.resultText);
  if (!parsed) {
    // The call succeeded and cost money, but didn't return a usable
    // response — still record that cost so a misbehaving/malformed
    // response can't be used to bypass the cap.
    return recordMiss(db, params, diffSummary, "error", envelope.totalCostUsd);
  }

  if (!parsed.worthAsking) {
    const eventId = insertEvent(db, {
      timestamp: new Date().toISOString(),
      repo: params.repo,
      sessionId,
      diffHash: params.diffHash,
      diffSummary,
      questionConcept: null,
      questionInstance: null,
      questionType: null,
      generationSource: GENERATION_SOURCE,
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: envelope.totalCostUsd,
      diffFiles: null,
    });
    return { eventId, missReason: null, questionType: null };
  }

  // worthAsking === true. The model was told the already-answered list and
  // instructed to self-censor, but Grasp still enforces the §3.2 rule
  // deterministically against its own DB — the model's own judgment isn't
  // trusted as the sole authority for a correctness guarantee.
  const alreadyAnswered = getConceptTagGlobal(db, parsed.conceptTag as string, true).length > 0;
  const includeConceptQuestion = parsed.questionConcept !== null && !alreadyAnswered;
  const questionType: "instance" | "both" = includeConceptQuestion ? "both" : "instance";

  const eventId = insertEvent(
    db,
    {
      timestamp: new Date().toISOString(),
      repo: params.repo,
      sessionId,
      diffHash: params.diffHash,
      diffSummary,
      questionConcept: includeConceptQuestion ? parsed.questionConcept : null,
      questionInstance: parsed.questionInstance,
      questionType,
      generationSource: GENERATION_SOURCE,
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: envelope.totalCostUsd,
      // Persisted verbatim so `grasp review` renders exactly what the judge
      // model saw — no re-fetch from git, no re-running the Phase 4 filter
      // against a working tree that may have moved on since.
      diffFiles: significantFiles,
    },
    [{ tag: parsed.conceptTag as string, answered: false }]
  );

  return { eventId, missReason: null, questionType };
}
import Database from "better-sqlite3";
import * as fs from "fs";
import { DB_PATH, GRASP_HOME } from "./paths";
import { CapturedDiff, DiffFile } from "./adapters/agentAdapter";
import { ConceptTagGlobalRow, ConceptTagRecord, EventRecord } from "./types";

const SCHEMA_SQL = `
  CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    repo TEXT NOT NULL,
    session_id TEXT,
    diff_hash TEXT,
    diff_summary TEXT,
    question_concept TEXT,
    question_instance TEXT,
    question_type TEXT,
    generation_source TEXT,
    miss_reason TEXT,
    answer_concept TEXT,
    answer_instance TEXT,
    skipped INTEGER NOT NULL DEFAULT 0,
    skip_reason TEXT,
    cost_usd REAL,
    diff_files_json TEXT
  );

  CREATE TABLE IF NOT EXISTS concept_tags (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL REFERENCES events(id),
    tag TEXT NOT NULL,
    answered INTEGER NOT NULL DEFAULT 0
  );

  CREATE INDEX IF NOT EXISTS idx_concept_tags_tag ON concept_tags(tag);

  -- idx_events_session_id is NOT created here: on a pre-Phase-5 database,
  -- the events table exists without the session_id column at this point
  -- (CREATE TABLE IF NOT EXISTS above is a no-op for it), and this file
  -- runs unconditionally on every openStore() call — creating an index on
  -- a column that may not exist yet would fail before migrateSchema() gets
  -- a chance to add it. See migrateSchema() below, which creates this
  -- index only after confirming/adding the column, safe for both fresh
  -- and pre-existing databases.

  -- Claude Code turn tracking: bridges hook firings, which are separate
  -- short-lived process invocations with no shared memory, into durable
  -- state keyed by Claude Code's own (session_id, prompt_id). See
  -- DECISIONS.md's "ClaudeCodeAdapter: session-state persistence across
  -- hook invocations" entry.
  CREATE TABLE IF NOT EXISTS cc_turns (
    session_id TEXT NOT NULL,
    prompt_id TEXT NOT NULL,
    repo TEXT NOT NULL,
    started_at TEXT NOT NULL,
    completed_at TEXT,
    PRIMARY KEY (session_id, prompt_id)
  );

  -- Diffs captured via PostToolUse during a turn, pending whatever Phase 5
  -- eventually does with them. Not the same table as \`events\` — \`events\`
  -- is reserved for actual question/miss rows (brief §3.5); a raw capture
  -- that never becomes a question doesn't belong there. \`filtered\`/
  -- \`filter_reason\` record Phase 4's mechanical-filter verdict on this
  -- capture — see DECISIONS.md's "Filtered-diff recording" entry: a
  -- filtered-out capture is still recorded here, never silently dropped.
  CREATE TABLE IF NOT EXISTS captured_diffs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id TEXT NOT NULL,
    prompt_id TEXT NOT NULL,
    repo TEXT NOT NULL,
    captured_at TEXT NOT NULL,
    diff_json TEXT NOT NULL,
    filtered INTEGER NOT NULL DEFAULT 0,
    filter_reason TEXT,
    FOREIGN KEY (session_id, prompt_id) REFERENCES cc_turns(session_id, prompt_id)
  );

  CREATE INDEX IF NOT EXISTS idx_captured_diffs_turn ON captured_diffs(session_id, prompt_id);

  -- Append-only audit trail of every hook firing Grasp observed. Exists
  -- because hook stdout isn't surfaced to the user, so this is the only
  -- durable, inspectable way to confirm hook behavior (e.g. that Stop
  -- really fired once per turn, not once per tool call).
  CREATE TABLE IF NOT EXISTS hook_invocations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id TEXT NOT NULL,
    prompt_id TEXT NOT NULL,
    event_name TEXT NOT NULL,
    invoked_at TEXT NOT NULL
  );

  CREATE INDEX IF NOT EXISTS idx_hook_invocations_turn ON hook_invocations(session_id, prompt_id, event_name);

  -- One row per (session_id, repo): the tree SHA of the working-tree
  -- snapshot the most recent capture for that session+repo was diffed up
  -- TO — i.e. "everything Grasp has already looked at." Read/advanced by
  -- ClaudeCodeAdapter's checkpoint-based incremental capture, which diffs
  -- each new PostToolUse firing against this instead of always against
  -- HEAD. See DECISIONS.md's "Checkpoint-based incremental capture" entry.
  CREATE TABLE IF NOT EXISTS capture_checkpoints (
    session_id TEXT NOT NULL,
    repo TEXT NOT NULL,
    tree_sha TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (session_id, repo)
  );
`;

/**
 * Adds columns to tables that already existed before the phase that
 * introduced them, for databases created by an earlier install. `CREATE
 * TABLE IF NOT EXISTS` in SCHEMA_SQL only covers brand-new databases; a
 * table that already exists keeps its original columns until migrated
 * explicitly.
 */
function migrateSchema(db: Database.Database): void {
  const capturedDiffsColumns = db.prepare(`PRAGMA table_info(captured_diffs)`).all() as Array<{
    name: string;
  }>;
  const capturedDiffsColumnNames = new Set(capturedDiffsColumns.map((c) => c.name));
  if (!capturedDiffsColumnNames.has("filtered")) {
    db.exec(`ALTER TABLE captured_diffs ADD COLUMN filtered INTEGER NOT NULL DEFAULT 0`);
  }
  if (!capturedDiffsColumnNames.has("filter_reason")) {
    db.exec(`ALTER TABLE captured_diffs ADD COLUMN filter_reason TEXT`);
  }

  const eventsColumns = db.prepare(`PRAGMA table_info(events)`).all() as Array<{ name: string }>;
  const eventsColumnNames = new Set(eventsColumns.map((c) => c.name));
  if (!eventsColumnNames.has("session_id")) {
    db.exec(`ALTER TABLE events ADD COLUMN session_id TEXT`);
  }
  if (!eventsColumnNames.has("diff_files_json")) {
    db.exec(`ALTER TABLE events ADD COLUMN diff_files_json TEXT`);
  }
  // Unconditional (not just inside the branch above): on a fresh install
  // SCHEMA_SQL's CREATE TABLE already includes session_id, so the ALTER
  // above is skipped, but the index still needs creating exactly once —
  // IF NOT EXISTS makes this safe to run every time regardless of path.
  db.exec(`CREATE INDEX IF NOT EXISTS idx_events_session_id ON events(session_id)`);
}

/**
 * How long a connection waits on a lock held by another Grasp process
 * before giving up. WAL mode (below) already lets readers proceed
 * concurrently with a writer, but two WRITERS (e.g. two hook firings for
 * overlapping tool calls, or a hook firing while `grasp review` is
 * mid-answer) can still contend for SQLite's single write lock.
 * better-sqlite3 already defaults its own internal busy-wait to 5000ms even
 * without this — verified by reading its source, not assumed — so this
 * pragma is set explicitly anyway: it makes the timeout an intentional,
 * documented, easily-tunable product decision instead of an implicit
 * dependency default a future reader wouldn't know exists (and one a future
 * major version of better-sqlite3 could silently change), and 10s gives
 * modest extra headroom over that default for a loaded machine. See
 * DECISIONS.md's "SQLite busy_timeout" entry for the full empirical story,
 * including a real edge case this does NOT fully close (many processes
 * racing to create/WAL-ify a brand-new database file simultaneously) and
 * why that gap doesn't matter for Grasp's actual architecture.
 */
const BUSY_TIMEOUT_MS = 10000;

export function openStore(dbPath: string = DB_PATH): Database.Database {
  fs.mkdirSync(GRASP_HOME, { recursive: true });
  const db = new Database(dbPath);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  db.pragma(`busy_timeout = ${BUSY_TIMEOUT_MS}`);
  db.exec(SCHEMA_SQL);
  migrateSchema(db);
  return db;
}

function toEventRow(event: EventRecord) {
  return {
    timestamp: event.timestamp,
    repo: event.repo,
    sessionId: event.sessionId,
    diffHash: event.diffHash,
    diffSummary: event.diffSummary,
    questionConcept: event.questionConcept,
    questionInstance: event.questionInstance,
    questionType: event.questionType,
    generationSource: event.generationSource,
    missReason: event.missReason,
    answerConcept: event.answerConcept,
    answerInstance: event.answerInstance,
    skipped: event.skipped ? 1 : 0,
    skipReason: event.skipReason,
    costUsd: event.costUsd,
    diffFilesJson: event.diffFiles ? JSON.stringify(event.diffFiles) : null,
  };
}

function fromEventRow(row: any): EventRecord {
  return {
    id: row.id,
    timestamp: row.timestamp,
    repo: row.repo,
    sessionId: row.session_id,
    diffHash: row.diff_hash,
    diffSummary: row.diff_summary,
    questionConcept: row.question_concept,
    questionInstance: row.question_instance,
    questionType: row.question_type,
    generationSource: row.generation_source,
    missReason: row.miss_reason,
    answerConcept: row.answer_concept,
    answerInstance: row.answer_instance,
    skipped: Boolean(row.skipped),
    skipReason: row.skip_reason,
    costUsd: row.cost_usd,
    diffFiles: row.diff_files_json ? JSON.parse(row.diff_files_json) : null,
  };
}

/**
 * Inserts one event row plus any linked concept_tags rows, in a single
 * transaction. Returns the new event's id.
 */
export function insertEvent(
  db: Database.Database,
  event: EventRecord,
  tags: Array<Pick<ConceptTagRecord, "tag" | "answered">> = []
): number {
  const insertEventStmt = db.prepare(`
    INSERT INTO events (
      timestamp, repo, session_id, diff_hash, diff_summary,
      question_concept, question_instance, question_type, generation_source,
      miss_reason, answer_concept, answer_instance,
      skipped, skip_reason, cost_usd, diff_files_json
    ) VALUES (
      @timestamp, @repo, @sessionId, @diffHash, @diffSummary,
      @questionConcept, @questionInstance, @questionType, @generationSource,
      @missReason, @answerConcept, @answerInstance,
      @skipped, @skipReason, @costUsd, @diffFilesJson
    )
  `);
  const insertTagStmt = db.prepare(
    `INSERT INTO concept_tags (event_id, tag, answered) VALUES (?, ?, ?)`
  );

  const runInTransaction = db.transaction(
    (evt: EventRecord, tagList: Array<Pick<ConceptTagRecord, "tag" | "answered">>) => {
      const info = insertEventStmt.run(toEventRow(evt));
      const eventId = Number(info.lastInsertRowid);
      for (const tag of tagList) {
        insertTagStmt.run(eventId, tag.tag, tag.answered ? 1 : 0);
      }
      return eventId;
    }
  );

  return runInTransaction(event, tags);
}

export function getEventById(db: Database.Database, id: number): EventRecord | undefined {
  const row = db.prepare(`SELECT * FROM events WHERE id = ?`).get(id);
  return row ? fromEventRow(row) : undefined;
}

export function getEventsByRepo(db: Database.Database, repo: string): EventRecord[] {
  const rows = db
    .prepare(`SELECT * FROM events WHERE repo = ? ORDER BY timestamp ASC`)
    .all(repo);
  return rows.map(fromEventRow);
}

export function getConceptTagsByEventId(
  db: Database.Database,
  eventId: number
): ConceptTagRecord[] {
  const rows = db
    .prepare(`SELECT * FROM concept_tags WHERE event_id = ?`)
    .all(eventId) as any[];
  return rows.map((row) => ({
    id: row.id,
    eventId: row.event_id,
    tag: row.tag,
    answered: Boolean(row.answered),
  }));
}

/**
 * Marks every concept_tags row linked to this event as answered, and
 * records the answer text on the event itself. Originally written to back
 * `debug:answer` (Phase 5) as a stand-in for real answering; Phase 7's
 * `grasp review` now calls this directly for genuine user answers too —
 * same function, not duplicated, per DECISIONS.md's memoization-wiring
 * note. Returns the tags that were updated (empty if the event had none,
 * e.g. a miss row — though `review` never calls this on a miss).
 */
export function markEventAnswered(
  db: Database.Database,
  eventId: number,
  answers: { answerConcept: string | null; answerInstance: string | null }
): string[] {
  const tags = getConceptTagsByEventId(db, eventId);

  const runInTransaction = db.transaction(() => {
    db.prepare(`UPDATE concept_tags SET answered = 1 WHERE event_id = ?`).run(eventId);
    db.prepare(`UPDATE events SET answer_concept = ?, answer_instance = ? WHERE id = ?`).run(
      answers.answerConcept,
      answers.answerInstance,
      eventId
    );
  });
  runInTransaction();

  return tags.map((t) => t.tag);
}

/**
 * Marks an event skipped. Per DECISIONS.md's "skip skips the whole event"
 * entry: the schema has one `skipped`/`skip_reason` pair per event, not
 * per sub-question, so this is all-or-nothing even for a "both" question —
 * there's no partial-skip state to represent.
 */
export function markEventSkipped(
  db: Database.Database,
  eventId: number,
  skipReason: string | null
): void {
  db.prepare(`UPDATE events SET skipped = 1, skip_reason = ? WHERE id = ?`).run(skipReason, eventId);
}

const PENDING_QUESTION_WHERE = `
  question_type IS NOT NULL
  AND skipped = 0
  AND answer_instance IS NULL
`;

/**
 * Every real (non-miss), unanswered, unskipped question across ALL repos —
 * deliberately global, matching the project's existing concept-tag
 * memoization precedent, not scoped to the current working directory's
 * repo. See DECISIONS.md's "grasp review query scope" entry for why.
 * `answer_instance IS NULL` alone is a reliable "not yet answered" check:
 * every real question (question_type "both" or "instance") always has a
 * non-null question_instance and gets it answered last in `review`'s
 * concept-then-instance sequence, so it's null iff the event is still
 * pending regardless of question_type.
 */
export function getPendingQuestions(db: Database.Database): EventRecord[] {
  const rows = db
    .prepare(`SELECT * FROM events WHERE ${PENDING_QUESTION_WHERE} ORDER BY timestamp ASC`)
    .all();
  return rows.map(fromEventRow);
}

/**
 * Same "pending question" definition, scoped to one Claude Code
 * `session_id` — what the `PreToolUse` hard-gate check and the `Stop`
 * nudge both use (see DECISIONS.md's "gate-check scope" entry): whether
 * *this session's own* work has an unanswered question outstanding, not
 * whether the user has anything pending anywhere.
 */
export function getPendingQuestionsForSession(
  db: Database.Database,
  sessionId: string
): EventRecord[] {
  const rows = db
    .prepare(
      `SELECT * FROM events WHERE ${PENDING_QUESTION_WHERE} AND session_id = ? ORDER BY timestamp ASC`
    )
    .all(sessionId);
  return rows.map(fromEventRow);
}

/**
 * Looks up a concept tag across ALL repos for the current user — deliberately
 * not scoped to one repo. This is what the future memoization check
 * ("has this concept been taught before, anywhere") reads from; nothing
 * calls it yet in Phase 1.
 */
export function getConceptTagGlobal(
  db: Database.Database,
  tag: string,
  onlyAnswered = true
): ConceptTagGlobalRow[] {
  const sql = `
    SELECT concept_tags.*, events.repo AS repo, events.timestamp AS event_timestamp
    FROM concept_tags
    JOIN events ON events.id = concept_tags.event_id
    WHERE concept_tags.tag = ?
    ${onlyAnswered ? "AND concept_tags.answered = 1" : ""}
    ORDER BY events.timestamp ASC
  `;
  const rows = db.prepare(sql).all(tag) as any[];
  return rows.map((row) => ({
    id: row.id,
    eventId: row.event_id,
    tag: row.tag,
    answered: Boolean(row.answered),
    repo: row.repo,
    eventTimestamp: row.event_timestamp,
  }));
}

/**
 * Every distinct concept tag answered (not skipped) anywhere, globally —
 * the "already-answered" list Phase 5 puts in the judge prompt so the
 * model can avoid proposing a concept question for something the user has
 * already demonstrated understanding of. Complements `getConceptTagGlobal`
 * (a point lookup for one tag); this is the "list them all" counterpart.
 */
export function getAllAnsweredConceptTags(db: Database.Database): string[] {
  const rows = db
    .prepare(`SELECT DISTINCT tag FROM concept_tags WHERE answered = 1 ORDER BY tag ASC`)
    .all() as Array<{ tag: string }>;
  return rows.map((row) => row.tag);
}

/**
 * Sums `cost_usd` across every `events` row for one Claude Code
 * `session_id` — the cost-cap accounting boundary resolved in
 * DECISIONS.md's "Resolving Phase 3's flagged consequence" entry: session-
 * wide, not per-turn. NULL `cost_usd` (e.g. a cap_reached miss that never
 * invoked the model) contributes 0.
 */
export function getSessionCostUsd(db: Database.Database, sessionId: string): number {
  const row = db
    .prepare(`SELECT COALESCE(SUM(cost_usd), 0) AS total FROM events WHERE session_id = ?`)
    .get(sessionId) as { total: number };
  return row.total;
}

/**
 * Counts real (non-miss) questions — `question_type IS NOT NULL` — for one
 * Claude Code `session_id`, across every turn sharing it. This is the
 * questions-per-session cap's accounting boundary (Phase 8): session-wide,
 * the same boundary `getSessionCostUsd` already uses for the cost cap, per
 * DECISIONS.md's "Resolving Phase 3's flagged consequence" entry — a
 * per-turn cap would let a long multi-turn session generate a fresh batch
 * on every turn, defeating the cap's purpose.
 */
export function getSessionQuestionCount(db: Database.Database, sessionId: string): number {
  const row = db
    .prepare(`SELECT COUNT(*) AS n FROM events WHERE session_id = ? AND question_type IS NOT NULL`)
    .get(sessionId) as { n: number };
  return row.n;
}

export interface TurnKey {
  sessionId: string;
  promptId: string;
}

/**
 * Ensures a `cc_turns` row exists for (sessionId, promptId). Safe to call
 * repeatedly across separate hook-invocation processes — `INSERT OR IGNORE`
 * makes the first caller for a given turn the one that sets `started_at`;
 * every later caller for the same turn is a no-op.
 */
export function upsertTurn(
  db: Database.Database,
  key: TurnKey & { repo: string }
): void {
  db.prepare(
    `INSERT OR IGNORE INTO cc_turns (session_id, prompt_id, repo, started_at) VALUES (?, ?, ?, ?)`
  ).run(key.sessionId, key.promptId, key.repo, new Date().toISOString());
}

/**
 * Marks a turn complete. Returns true only if THIS call was the one that
 * transitioned it from incomplete -> complete (the `WHERE completed_at IS
 * NULL` makes this atomic and idempotent at the DB level) — so a second
 * Stop firing for the same turn, however it happened, safely no-ops
 * instead of re-running completion side effects.
 */
export function completeTurn(db: Database.Database, key: TurnKey): boolean {
  const info = db
    .prepare(
      `UPDATE cc_turns SET completed_at = ? WHERE session_id = ? AND prompt_id = ? AND completed_at IS NULL`
    )
    .run(new Date().toISOString(), key.sessionId, key.promptId);
  return info.changes > 0;
}

export function getTurn(
  db: Database.Database,
  key: TurnKey
): { sessionId: string; promptId: string; repo: string; startedAt: string; completedAt: string | null } | undefined {
  const row = db
    .prepare(`SELECT * FROM cc_turns WHERE session_id = ? AND prompt_id = ?`)
    .get(key.sessionId, key.promptId) as any;
  if (!row) return undefined;
  return {
    sessionId: row.session_id,
    promptId: row.prompt_id,
    repo: row.repo,
    startedAt: row.started_at,
    completedAt: row.completed_at,
  };
}

/**
 * The checkpoint tree SHA the most recent capture for this (session, repo)
 * was diffed up to — null if no capture has happened yet for this pair
 * (i.e. this hook firing is the first Grasp has ever seen for it).
 */
export function getCheckpointTree(db: Database.Database, sessionId: string, repo: string): string | null {
  const row = db
    .prepare(`SELECT tree_sha FROM capture_checkpoints WHERE session_id = ? AND repo = ?`)
    .get(sessionId, repo) as { tree_sha: string } | undefined;
  return row ? row.tree_sha : null;
}

/**
 * Advances (or first-establishes) the checkpoint for a (session, repo)
 * pair to `treeSha`. Always overwrites — a checkpoint only ever moves
 * forward to "the state as of the capture that just ran," never backward.
 */
export function setCheckpointTree(
  db: Database.Database,
  sessionId: string,
  repo: string,
  treeSha: string
): void {
  db.prepare(
    `INSERT INTO capture_checkpoints (session_id, repo, tree_sha, updated_at) VALUES (?, ?, ?, ?)
     ON CONFLICT(session_id, repo) DO UPDATE SET tree_sha = excluded.tree_sha, updated_at = excluded.updated_at`
  ).run(sessionId, repo, treeSha, new Date().toISOString());
}

/**
 * Persists a captured diff for a turn, along with Phase 4's mechanical
 * filter verdict — `filtered: false, filterReason: null` for a diff that
 * passed, `filtered: true, filterReason: <reason>` for one that didn't.
 * Every capture gets a row here regardless of verdict; nothing is silently
 * dropped (see DECISIONS.md's "Filtered-diff recording" entry).
 * `upsertTurn` must have been called first (FK).
 */
export function insertCapturedDiff(
  db: Database.Database,
  key: TurnKey & {
    repo: string;
    capturedAt: string;
    diff: CapturedDiff;
    filtered: boolean;
    filterReason: string | null;
  }
): number {
  const info = db
    .prepare(
      `INSERT INTO captured_diffs (session_id, prompt_id, repo, captured_at, diff_json, filtered, filter_reason)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    )
    .run(
      key.sessionId,
      key.promptId,
      key.repo,
      key.capturedAt,
      JSON.stringify(key.diff),
      key.filtered ? 1 : 0,
      key.filterReason
    );
  return Number(info.lastInsertRowid);
}

export interface CapturedDiffRecord {
  id: number;
  capturedAt: string;
  diff: CapturedDiff;
  filtered: boolean;
  filterReason: string | null;
}

export function getCapturedDiffsForTurn(
  db: Database.Database,
  key: TurnKey
): CapturedDiffRecord[] {
  const rows = db
    .prepare(
      `SELECT id, captured_at, diff_json, filtered, filter_reason FROM captured_diffs
       WHERE session_id = ? AND prompt_id = ? ORDER BY captured_at ASC`
    )
    .all(key.sessionId, key.promptId) as any[];
  return rows.map((row) => ({
    id: row.id,
    capturedAt: row.captured_at,
    diff: JSON.parse(row.diff_json),
    filtered: Boolean(row.filtered),
    filterReason: row.filter_reason,
  }));
}

/** Append-only audit row — every observed hook firing, regardless of what (if anything) it did. */
export function recordHookInvocation(
  db: Database.Database,
  key: TurnKey & { eventName: string }
): void {
  db.prepare(
    `INSERT INTO hook_invocations (session_id, prompt_id, event_name, invoked_at) VALUES (?, ?, ?, ?)`
  ).run(key.sessionId, key.promptId, key.eventName, new Date().toISOString());
}

export function countHookInvocations(
  db: Database.Database,
  key: TurnKey & { eventName: string }
): number {
  const row = db
    .prepare(
      `SELECT COUNT(*) as n FROM hook_invocations WHERE session_id = ? AND prompt_id = ? AND event_name = ?`
    )
    .get(key.sessionId, key.promptId, key.eventName) as any;
  return row.n as number;
}

#!/usr/bin/env node
// A controllable stand-in for the real `claude` CLI, used by test/caps.test.ts
// to exercise runGeneration's cap/cost logic without a real Claude Code
// subscription. Behavior is selected via env vars, matching the pattern used
// throughout this project's manual verification (mock claude binaries on PATH).
const fs = require("fs");

const mode = process.env.GRASP_TEST_MOCK_MODE || "normal";

if (mode === "error") {
  process.stdout.write(JSON.stringify({ total_cost_usd: 0.001, result: "", is_error: true }));
  process.exit(0);
}

if (mode === "bad-json-result") {
  // Envelope itself is well-formed and reports a real cost, but `result`
  // isn't the expected JSON contract — proves cost is still recorded on a
  // malformed-response miss (see DECISIONS.md's malformed-response entry).
  process.stdout.write(JSON.stringify({ total_cost_usd: 0.002, result: "not valid json at all", is_error: false }));
  process.exit(0);
}

if (mode === "missing-cost") {
  const result = {
    worthAsking: true,
    conceptTag: "missing-cost-tag",
    questionConcept: "concept q",
    questionInstance: "instance q",
  };
  process.stdout.write(JSON.stringify({ result: JSON.stringify(result), is_error: false }));
  process.exit(0);
}

// mode === "normal": always worth asking, fresh concept tag per call (via a
// counter file) so memoization never suppresses the concept question.
const counterPath = process.env.GRASP_TEST_MOCK_COUNTER;
let n = 0;
if (counterPath) {
  try {
    n = parseInt(fs.readFileSync(counterPath, "utf-8"), 10) || 0;
  } catch {
    n = 0;
  }
  n += 1;
  fs.writeFileSync(counterPath, String(n));
}
const cost = process.env.GRASP_TEST_MOCK_COST ? parseFloat(process.env.GRASP_TEST_MOCK_COST) : 0.001;
const result = {
  worthAsking: true,
  conceptTag: `test-concept-${n}`,
  questionConcept: `concept question ${n}`,
  questionInstance: `instance question ${n}`,
};
process.stdout.write(JSON.stringify({ total_cost_usd: cost, result: JSON.stringify(result), is_error: false }));
}

/** True when a caught execFileSync error is specifically a timeout kill, not any other failure (spawn error, nonzero exit, ...). Empirically verified (not assumed) against this Node version: a timeout sets `error.code === "ETIMEDOUT"` — `error.killed` is NOT reliably `true` the way Node's own docs might suggest, and `error.signal === "SIGTERM"` alone isn't a safe-enough signal on its own since a process could plausibly exit via SIGTERM for unrelated reasons. See DECISIONS.md's "Timeout detection mechanism" entry. */
export function isTimeoutError(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { code?: unknown }).code === "ETIMEDOUT";
}

/** Shells out to `claude -p`, exactly per brief §3.3's recommended invocation shape. Throws if the process fails, times out, or its stdout isn't valid JSON at all — callers must catch, and can use `isTimeoutError` to distinguish a timeout from any other failure. */
function invokeClaudeJudge(prompt: string): ClaudeEnvelope {
  const stdout = execFileSync(
    "claude",
    ["-p", prompt, "--output-format", "json", "--allowedTools", "", "--max-turns", "1"],
    { encoding: "utf-8", maxBuffer: 1024 * 1024 * 16, timeout: GENERATION_TIMEOUT_MS }
  );
  const envelope = JSON.parse(stdout);
  return {
    totalCostUsd: typeof envelope.total_cost_usd === "number" ? envelope.total_cost_usd : null,
    resultText: typeof envelope.result === "string" ? envelope.result : "",
    isError: Boolean(envelope.is_error),
  };
}

export interface JudgeResponse {
  worthAsking: boolean;
  conceptTag: string | null;
  questionConcept: string | null;
  questionInstance: string | null;
}

/** Strips a ```json ... ``` / ``` ... ``` fence if the model wrapped its JSON in one despite instructions not to. */
function extractJsonBlock(text: string): string {
  const trimmed = text.trim();
  const fenceMatch = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  return fenceMatch ? fenceMatch[1].trim() : trimmed;
}

/** Returns null for anything that doesn't match the contract — malformed JSON, wrong types, or an internally inconsistent shape. Never throws. */
export function parseJudgeResponse(raw: string): JudgeResponse | null {
  let obj: any;
  try {
    obj = JSON.parse(extractJsonBlock(raw));
  } catch {
    return null;
  }
  if (typeof obj !== "object" || obj === null) return null;
  if (typeof obj.worthAsking !== "boolean") return null;

  if (obj.worthAsking === false) {
    if (obj.conceptTag !== null || obj.questionConcept !== null || obj.questionInstance !== null) {
      return null;
    }
    return { worthAsking: false, conceptTag: null, questionConcept: null, questionInstance: null };
  }

  if (typeof obj.conceptTag !== "string" || obj.conceptTag.trim().length === 0) return null;
  if (typeof obj.questionInstance !== "string" || obj.questionInstance.trim().length === 0) return null;
  if (
    obj.questionConcept !== null &&
    (typeof obj.questionConcept !== "string" || obj.questionConcept.trim().length === 0)
  ) {
    return null;
  }

  return {
    worthAsking: true,
    conceptTag: obj.conceptTag.trim(),
    questionConcept: typeof obj.questionConcept === "string" ? obj.questionConcept.trim() : null,
    questionInstance: obj.questionInstance.trim(),
  };
}

// --- main entry point --------------------------------------------------------

function recordMiss(
  db: Database.Database,
  params: GenerationParams,
  diffSummary: string,
  missReason: MissReason,
  costUsd: number | null
): GenerationOutcome {
  const eventId = insertEvent(db, {
    timestamp: new Date().toISOString(),
    repo: params.repo,
    sessionId: params.sessionId,
    diffHash: params.diffHash,
    diffSummary,
    questionConcept: null,
    questionInstance: null,
    questionType: null,
    generationSource: GENERATION_SOURCE,
    missReason,
    answerConcept: null,
    answerInstance: null,
    skipped: false,
    skipReason: null,
    costUsd,
    diffFiles: null,
  });
  return { eventId, missReason, questionType: null };
}

/**
 * Given a diff that already passed Phase 4's mechanical filter, enforces
 * the session-wide cost cap, then (if not capped) runs the single judge+
 * generate call and writes exactly one `events` row — whether or not it
 * produced a question. See DECISIONS.md's prompt/response-contract and
 * malformed-response entries for the design reasoning.
 */
export function runGeneration(db: Database.Database, params: GenerationParams): GenerationOutcome {
  const { sessionId, significantFiles, config } = params;
  const diffSummary = buildDiffSummary(significantFiles);

  const spentSoFar = getSessionCostUsd(db, sessionId);
  if (spentSoFar >= config.costCapUsd) {
    // Cap already met/exceeded — never invoke `claude -p` at all.
    return recordMiss(db, params, diffSummary, "cap_reached", null);
  }

  const questionsSoFar = getSessionQuestionCount(db, sessionId);
  if (questionsSoFar >= config.questionsPerSessionCap) {
    // Same "never invoke claude -p at all" pattern as the cost cap above,
    // and the same miss_reason — see DECISIONS.md's "Questions-per-session
    // cap: miss-reason reuse" entry for why cap_reached is shared rather
    // than a new value, and for how the two remain distinguishable after
    // the fact from the session's own cost/question totals at the time.
    return recordMiss(db, params, diffSummary, "cap_reached", null);
  }

  const answeredTags = getAllAnsweredConceptTags(db);
  const diffText = formatDiffForPrompt(significantFiles);
  const prompt = buildJudgePrompt(diffText, answeredTags);

  let envelope: ClaudeEnvelope;
  try {
    envelope = invokeClaudeJudge(prompt);
  } catch (err) {
    // Process never produced a usable envelope at all — no cost figure to
    // record either way (genuinely unknown, not 0). A timeout kill is
    // distinguished from every other spawn/exit failure specifically —
    // see isTimeoutError's own comment for how that's actually detected.
    const missReason: MissReason = isTimeoutError(err) ? "timeout" : "error";
    return recordMiss(db, params, diffSummary, missReason, null);
  }

  if (envelope.isError) {
    return recordMiss(db, params, diffSummary, "error", envelope.totalCostUsd);
  }

  if (envelope.totalCostUsd === null) {
    // A well-formed, non-error envelope that's missing its own cost figure
    // can't be trusted for cap accounting — recording it as a "free"
    // successful call would let repeated uncosted responses bypass the
    // cost cap entirely (it sums cost_usd, and NULL contributes 0). Treat
    // it as a miss instead — see DECISIONS.md's "Missing total_cost_usd"
    // entry. This intentionally never reaches parseJudgeResponse: even a
    // perfectly well-formed question in this response isn't recorded,
    // since there's no way to know what it actually cost.
    return recordMiss(db, params, diffSummary, "error", null);
  }

  const parsed = parseJudgeResponse(envelope.resultText);
  if (!parsed) {
    // The call succeeded and cost money, but didn't return a usable
    // response — still record that cost so a misbehaving/malformed
    // response can't be used to bypass the cap.
    return recordMiss(db, params, diffSummary, "error", envelope.totalCostUsd);
  }

  if (!parsed.worthAsking) {
    const eventId = insertEvent(db, {
      timestamp: new Date().toISOString(),
      repo: params.repo,
      sessionId,
      diffHash: params.diffHash,
      diffSummary,
      questionConcept: null,
      questionInstance: null,
      questionType: null,
      generationSource: GENERATION_SOURCE,
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: envelope.totalCostUsd,
      diffFiles: null,
    });
    return { eventId, missReason: null, questionType: null };
  }

  // worthAsking === true. The model was told the already-answered list and
  // instructed to self-censor, but Grasp still enforces the §3.2 rule
  // deterministically against its own DB — the model's own judgment isn't
  // trusted as the sole authority for a correctness guarantee.
  const alreadyAnswered = getConceptTagGlobal(db, parsed.conceptTag as string, true).length > 0;
  const includeConceptQuestion = parsed.questionConcept !== null && !alreadyAnswered;
  const questionType: "instance" | "both" = includeConceptQuestion ? "both" : "instance";

  const eventId = insertEvent(
    db,
    {
      timestamp: new Date().toISOString(),
      repo: params.repo,
      sessionId,
      diffHash: params.diffHash,
      diffSummary,
      questionConcept: includeConceptQuestion ? parsed.questionConcept : null,
      questionInstance: parsed.questionInstance,
      questionType,
      generationSource: GENERATION_SOURCE,
      missReason: null,
      answerConcept: null,
      answerInstance: null,
      skipped: false,
      skipReason: null,
      costUsd: envelope.totalCostUsd,
      // Persisted verbatim so `grasp review` renders exactly what the judge
      // model saw — no re-fetch from git, no re-running the Phase 4 filter
      // against a working tree that may have moved on since.
      diffFiles: significantFiles,
    },
    [{ tag: parsed.conceptTag as string, answered: false }]
  );

  return { eventId, missReason: null, questionType };
}
import * as React from "react";
import type { InkModules } from "./inkLoader";
import type { DiffFile } from "./adapters/agentAdapter";
import type { EventRecord } from "./types";

const { useState, useEffect, useCallback } = React;

/**
 * `grasp review`'s TUI, built as a factory over the dynamically-loaded ink
 * module (see inkLoader.ts) rather than importing `ink`'s components as
 * module-level values — JSX only needs `Box`/`Text`/etc. to be identifiers
 * in *scope*, not module-top-level imports, so closing over them here
 * works exactly like a normal import would from React's perspective.
 */

export interface ReviewAnswers {
  answerConcept: string | null;
  answerInstance: string | null;
}

/**
 * One pending question plus its position within the Phase 8 batch grouping
 * (see review.ts's `groupForBatchPresentation`) — same session's questions
 * stay adjacent and this carries enough to render that context ("2 of 3 in
 * this session's batch") without the component needing to recompute
 * grouping itself.
 */
export interface ReviewQueueItem {
  event: EventRecord;
  sessionPosition: number;
  sessionSize: number;
  batchIndex: number;
  batchCount: number;
}

export interface ReviewAppProps {
  items: ReviewQueueItem[];
  onAnswer: (eventId: number, answers: ReviewAnswers) => void;
  onSkip: (eventId: number, skipReason: string | null) => void;
}

interface RenderLine {
  text: string;
  kind: "file" | "hunk" | "add" | "del" | "context";
}

function flattenDiffFiles(files: DiffFile[]): RenderLine[] {
  const lines: RenderLine[] = [];
  for (const file of files) {
    const label = file.oldPath ? `${file.oldPath} -> ${file.path}` : file.path;
    lines.push({
      text: `${file.status.toUpperCase()}  ${label}  (+${file.insertions}/-${file.deletions})`,
      kind: "file",
    });
    for (const hunk of file.hunks) {
      lines.push({ text: hunk.header, kind: "hunk" });
      for (const l of hunk.lines) {
        const kind: RenderLine["kind"] = l.startsWith("+") ? "add" : l.startsWith("-") ? "del" : "context";
        lines.push({ text: l.length > 0 ? l : " ", kind });
      }
    }
  }
  return lines;
}

const LINE_COLOR: Record<RenderLine["kind"], string | undefined> = {
  file: undefined,
  hunk: "cyan",
  add: "green",
  del: "red",
  context: undefined,
};

type Phase = "concept" | "instance" | "skip-reason";
type Mode = "viewing" | "answering";

export function createReviewApp({ ink, TextInput }: InkModules) {
  const { Box, Text, useInput, useApp } = ink;

  /** Reactive terminal size — forces a re-render on resize (React state doesn't update on its own for external events). */
  function useTerminalSize() {
    const [, forceRender] = useState(0);
    useEffect(() => {
      const onResize = () => forceRender((n) => n + 1);
      process.stdout.on("resize", onResize);
      return () => {
        process.stdout.off("resize", onResize);
      };
    }, []);
    return {
      rows: process.stdout.rows || 24,
      columns: process.stdout.columns || 80,
    };
  }

  function DiffView({ lines, scrollOffset, maxRows }: { lines: RenderLine[]; scrollOffset: number; maxRows: number }) {
    const visible = lines.slice(scrollOffset, scrollOffset + maxRows);
    const hasMoreAbove = scrollOffset > 0;
    const hasMoreBelow = scrollOffset + maxRows < lines.length;
    return (
      <Box flexDirection="column" borderStyle="round" borderColor="gray" paddingX={1}>
        {hasMoreAbove ? <Text dimColor>↑ ({scrollOffset} more line{scrollOffset === 1 ? "" : "s"} above)</Text> : null}
        {visible.map((line, i) => (
          <Text key={scrollOffset + i} color={LINE_COLOR[line.kind]} bold={line.kind === "file"} wrap="truncate-end">
            {line.text}
